Here's a simple **Tic-Tac-Toe** game in a C# console program:

```csharp
using System;

class TicTacToe
{
    static char[] board = { '1', '2', '3', '4', '5', '6', '7', '8', '9' };
    static int currentPlayer = 1;

    static void Main(string[] args)
    {
        Console.Title = "Tic-Tac-Toe";
        int move;
        bool gameOver = false;

        Console.WriteLine("Welcome to Tic-Tac-Toe!");
        Console.WriteLine("========================\n");

        while (!gameOver)
        {
            DrawBoard();
            Console.Write($"\nPlayer {currentPlayer} ({(currentPlayer == 1 ? 'X' : 'O')}), enter your move (1-9): ");

            if (int.TryParse(Console.ReadLine(), out move) && move >= 1 && move <= 9)
            {
                if (board[move - 1] != 'X' && board[move - 1] != 'O')
                {
                    board[move - 1] = (currentPlayer == 1) ? 'X' : 'O';

                    if (CheckWinner())
                    {
                        DrawBoard();
                        Console.WriteLine($"\n🎉 Player {currentPlayer} wins! Congratulations!");
                        gameOver = true;
                    }
                    else if (IsBoardFull())
                    {
                        DrawBoard();
                        Console.WriteLine("\nIt's a Draw! Well played both!");
                        gameOver = true;
                    }
                    else
                    {
                        currentPlayer = (currentPlayer == 1) ? 2 : 1;
                    }
                }
                else
                {
                    Console.WriteLine("\n⚠️  That position is already taken! Try again.");
                    Console.ReadKey();
                }
            }
            else
            {
                Console.WriteLine("\n⚠️  Invalid input! Please enter a number between 1 and 9.");
                Console.ReadKey();
            }
        }

        Console.WriteLine("\nThanks for playing! Press any key to exit...");
        Console.ReadKey();
    }

    static void DrawBoard()
    {
        Console.Clear();
        Console.WriteLine("  Tic-Tac-Toe  ");
        Console.WriteLine("=================");
        Console.WriteLine($"  {board[0]} | {board[1]} | {board[2]}  ");
        Console.WriteLine(" ---+---+--- ");
        Console.WriteLine($"  {board[3]} | {board[4]} | {board[5]}  ");
        Console.WriteLine(" ---+---+--- ");
        Console.WriteLine($"  {board[6]} | {board[7]} | {board[8]}  ");
        Console.WriteLine("=================");
    }

    static bool CheckWinner()
    {
        // Check rows
        if (board[0] == board[1] && board[1] == board[2]) return true;
        if (board[3] == board[4] && board[4] == board[5]) return true;
        if (board[6] == board[7] && board[7] == board[8]) return true;

        // Check columns
        if (board[0] == board[3] && board[3] == board[6]) return true;
        if (board[1] == board[4] && board[4] == board[7]) return true;
        if (board[2] == board[5] && board[5] == board[8]) return true;

        // Check diagonals
        if (board[0] == board[4] && board[4] == board[8]) return true;
        if (board[2] == board[4] && board[4] == board[6]) return true;

        return false;
    }

    static bool IsBoardFull()
    {
        foreach (char c in board)
        {
            if (c != 'X' && c != 'O') return false;
        }
        return true;
    }
}
```

