### app/models/Booking.php
```php
<?php
class Booking {
    private $pdo;
    private $table = 'bookings';

    public function __construct($pdo) {
        $this->pdo = $pdo;
    }

    // Criar nova reserva
    public function create($data) {
        $sql = "INSERT INTO {$this->table} 
                (booking_code, user_id, room_id, check_in, 
                check_out, total_price, status, created_at)
                VALUES 
                (:booking_code, :user_id, :room_id, :check_in,
                :check_out, :total_price, 'pending', NOW())";

        $stmt = $this->pdo->prepare($sql);
        return $stmt->execute([
            ':booking_code' => generateBookingCode(),
            ':user_id'      => $data['user_id'],
            ':room_id'      => $data['room_id'],
            ':check_in'     => $data['check_in'],
            ':check_out'    => $data['check_out'],
            ':total_price'  => $data['total_price']
        ]);
    }

    // Buscar reservas por usuário
    public function getByUser($userId) {
        $sql = "SELECT b.*, r.name as room_name, r.price 
                FROM {$this->table} b
                JOIN rooms r ON b.room_id = r.id
                WHERE b.user_id = :user_id
                ORDER BY b.created_at DESC";

        $stmt = $this->pdo->prepare($sql);
        $stmt->execute([':user_id' => $userId]);
        return $stmt->fetchAll();
    }

    // Cancelar reserva
    public function cancel($bookingId, $userId) {
        $sql = "UPDATE {$this->table} 
                SET status = 'cancelled'
                WHERE id = :id AND user_id = :user_id";

        $stmt = $this->pdo->prepare($sql);
        return $stmt->execute([
            ':id'      => $bookingId,
            ':user_id' => $userId
        ]);
    }
}
