# ASP.NET Core User Model in C#

Here's a comprehensive user model for an ASP.NET Core application:

```csharp
using System;
using System.Collections.Generic;
using System.ComponentModel.DataAnnotations;
using System.ComponentModel.DataAnnotations.Schema;

namespace YourApp.Models
{
    public class User
    {
        // Primary Key
        [Key]
        [DatabaseGenerated(DatabaseGeneratedOption.Identity)]
        public int Id { get; set; }

        // Personal Information
        [Required(ErrorMessage = "First name is required")]
        [StringLength(50, MinimumLength = 2, ErrorMessage = "First name must be between 2 and 50 characters")]
        public string FirstName { get; set; }

        [Required(ErrorMessage = "Last name is required")]
        [StringLength(50, MinimumLength = 2, ErrorMessage = "Last name must be between 2 and 50 characters")]
        public string LastName { get; set; }

        [Required(ErrorMessage = "Email is required")]
        [EmailAddress(ErrorMessage = "Invalid email address")]
        [StringLength(100)]
        public string Email { get; set; }

        [Phone(ErrorMessage = "Invalid phone number")]
        [StringLength(20)]
        public string PhoneNumber { get; set; }

        [DataType(DataType.Date)]
        public DateTime? DateOfBirth { get; set; }

        // Authentication
        [Required(ErrorMessage = "Username is required")]
        [StringLength(50, MinimumLength = 3, ErrorMessage = "Username must be between 3 and 50 characters")]
        public string Username { get; set; }

        [Required]
        public string PasswordHash { get; set; }

        public string Salt { get; set; }

        // Role & Permissions
        [Required]
        public UserRole Role { get; set; } = UserRole.User;

        public bool IsActive { get; set; } = true;

        public bool IsEmailVerified { get; set; } = false;

        // Profile
        [StringLength(500)]
        public string Bio { get; set; }

        [Url(ErrorMessage = "Invalid URL")]
        public string ProfilePictureUrl { get; set; }

        // Address
        public Address Address { get; set; }

        // Timestamps
        public DateTime CreatedAt { get; set; } = DateTime.UtcNow;

        public DateTime? UpdatedAt { get; set; }

        public DateTime? LastLoginAt { get; set; }

        // Token Management
        public string RefreshToken { get; set; }

        public DateTime? RefreshTokenExpiry { get; set; }

        public string PasswordResetToken { get; set; }

        public DateTime? PasswordResetTokenExpiry { get; set; }

        // Navigation Properties
        public virtual ICollection<Post> Posts { get; set; } = new List<Post>();

        // Computed Property
        [NotMapped]
        public string FullName => $"{FirstName} {LastName}";

        [NotMapped]
        public int Age => DateOfBirth.HasValue
            ? DateTime.Today.Year - DateOfBirth.Value.Year -
              (DateTime.Today < DateOfBirth.Value.AddYears(DateTime.Today.Year - DateOfBirth.Value.Year) ? 1 : 0)
            : 0;
    }

    // Enum for User Roles
    public enum UserRole
    {
        Admin = 1,
