# C# Console App - Mathematical Expression Calculator

## Project Setup

Create a new C# Console App project and replace the contents of `Program.cs` with the following code:

```csharp
using System;
using System.Data;

namespace MathExpressionCalculator
{
    class Program
    {
        static void Main(string[] args)
        {
            Console.WriteLine("=================================");
            Console.WriteLine("  Mathematical Expression Calculator");
            Console.WriteLine("=================================");
            Console.WriteLine("Supported operators: +, -, *, /, ^, ()");
            Console.WriteLine("Type 'exit' to quit");
            Console.WriteLine();

            while (true)
            {
                Console.Write("Enter expression: ");
                string input = Console.ReadLine();

                if (string.IsNullOrWhiteSpace(input))
                {
                    Console.WriteLine("Please enter a valid expression.\n");
                    continue;
                }

                if (input.ToLower() == "exit")
                {
                    Console.WriteLine("Goodbye!");
                    break;
                }

                try
                {
                    double result = EvaluateExpression(input);
                    Console.WriteLine($"Result: {result}\n");
                }
                catch (DivideByZeroException)
                {
                    Console.WriteLine("Error: Division by zero!\n");
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"Error: {ex.Message}\n");
                }
            }
        }

        static double EvaluateExpression(string expression)
        {
            // Replace ^ with ** for power operator
            expression = expression.Replace("^", "**");

            // Remove whitespace
            expression = expression.Replace(" ", "");

            // Validate characters
            foreach (char c in expression)
            {
                if (!char.IsDigit(c) && c != '+' && c != '-' && c != '*'
                    && c != '/' && c != '(' && c != ')' && c != '.' && c != '^')
                {
                    throw new ArgumentException($"Invalid character '{c}' in expression.");
                }
            }

            return ParseExpression(expression, ref var index = 0);
        }

        // -------------------------------------------------------
        // Recursive Descent Parser
        // -------------------------------------------------------

        static double ParseExpression(string expr, ref int index)
        {
            double left = ParseTerm(expr, ref index);

            while (index < expr.Length &&
                   (expr[index] == '+' || expr[index] == '-'))
            {
                char op = expr[index++];
                double right = ParseTerm(expr, ref index);

                if (op == '+') left += right;
                else           left -= right;
            }

            return left;
        }

        static double ParseTerm(string expr, ref int index)
        {
            double left = ParsePower(expr, ref index);

            while (index < expr.Length &&
                   (expr[index] == '*' || expr[index] == '/'))
            {
                char op = expr[index++];

                // Handle ** (power) operator
                if (op == '*' && index < expr.Length && expr[index] == '*')
                {
                    index++;
                    double right = ParsePower(expr, ref index);
                    left = Math.Pow(left, right);
                }
                else
                {
                    double right = ParsePower(expr, ref index);
                    if (op == '*') left *= right;
                    else
                    {
                        if (right == 0) throw new DivideByZeroException();
                        left /= right;
                    }
                }
            }

            return left;
        }

        static double ParsePower(string expr, ref int index)
        {
            double baseVal = ParseFactor(expr, ref index);

            if (index < expr.Length && expr[index] == '^')
            {
                index++;
                double exponent = ParsePower(expr, ref index); // right-associative
                return Math.Pow(baseVal, exponent);
            }

            return baseVal;
        }

        static double ParseFactor(string expr, ref int index)
        {
            // Handle unary minus
            if (index < expr.Length && expr[index] == '-')
            {
                index++;
                return -ParseFactor(expr, ref index);
            }

            // Handle unary plus
            if (index < expr.Length && expr[index] == '+')
            {
                index++;
                return ParseFactor(expr, ref index);
            }

            // Handle parentheses
            if (index < expr.Length && expr[index] == '(')
            {
                index++; // skip '('
                double result = ParseExpression(expr, ref index);

                if (index >= expr.Length || expr[index] != ')')
                    throw new ArgumentException("Mismatched parentheses.");

                index++; // skip ')'
                return result;
            }

            // Handle numbers
            return ParseNumber(expr, ref index);
        }

        static double ParseNumber(string expr, ref int index)
        {
            int start = index;

            while (index < expr.Length &&
                   (char.IsDigit(expr[index]) || expr[index] == '.'))
            {
                index++;
            }

            if (start == index)
                throw new ArgumentException($"Unexpected character at position {index}.");

            string numberStr = expr.Substring(start, index - start);

            if (!double.TryParse(numberStr, out double number))
                throw new ArgumentException($"Invalid number: {numberStr}");

            return number;
        }
    }
}
```

---

## How It Works

| Component | Description |
|-----------|-------------|
| `ParseExpression` | Handles `+` and `-` (lowest precedence) |
| `ParseTerm` | Handles `*` and `/` (medium precedence) |
| `ParsePower` | Handles `^` power operator (high precedence, right-associative) |
| `ParseFactor` | Handles unary `+`/`-`, parentheses `()` |
| `ParseNumber` | Reads a numeric literal including decimals |

