# ESP-NOW Master Code Example

Here's a complete ESP-NOW **Master (Sender)** code example for ESP32:

---

## Master (Sender) Code

```cpp
#include <Arduino.h>
#include <esp_now.h>
#include <WiFi.h>

// =============================================
// Configuration
// =============================================

// Replace with your Slave MAC Address
uint8_t slaveMAC[] = {0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF};

// Data structure to send
typedef struct MessageData {
  int id;
  float temperature;
  float humidity;
  char message[32];
} MessageData;

MessageData dataToSend;
esp_now_peer_info_t peerInfo;

// =============================================
// Callback Functions
// =============================================

// Called when data is sent
void OnDataSent(const uint8_t *mac_addr, esp_now_send_status_t status) {
  Serial.print("Last Packet Send Status: ");
  if (status == ESP_NOW_SEND_SUCCESS) {
    Serial.println("✅ Delivery Success");
  } else {
    Serial.println("❌ Delivery Fail");
  }
}

// =============================================
// Setup
// =============================================

void setup() {
  Serial.begin(115200);
  Serial.println("\n=== ESP-NOW Master ===");

  // Set device as a Wi-Fi Station
  WiFi.mode(WIFI_STA);
  WiFi.disconnect();

  // Print MAC Address
  Serial.print("Master MAC Address: ");
  Serial.println(WiFi.macAddress());

  // Initialize ESP-NOW
  if (esp_now_init() != ESP_OK) {
    Serial.println("❌ Error initializing ESP-NOW");
    return;
  }

  // Register send callback
  esp_now_register_send_cb(OnDataSent);

  // Register peer (slave)
  memcpy(peerInfo.peer_addr, slaveMAC, 6);
  peerInfo.channel = 0;
  peerInfo.encrypt = false;

  if (esp_now_add_peer(&peerInfo) != ESP_OK) {
    Serial.println("❌ Failed to add peer");
    return;
  }

  Serial.println("✅ ESP-NOW Initialized");
  Serial.println("✅ Peer Added Successfully");
}

// =============================================
// Loop
// =============================================

void loop() {
  // Populate data
  dataToSend.id++;
  dataToSend.temperature = random(200, 350) / 10.0;  // 20.0 - 35.0
  dataToSend.humidity    = random(400, 900) / 10.0;  // 40.0 - 90.0
  snprintf(dataToSend.message, sizeof(dataToSend.message), "Hello from Master #%d", dataToSend.id);

  // Send data
  esp_err_t result = esp_now_send(slaveMAC, (uint8_t *)&dataToSend, sizeof(dataToSend));

  if (result == ESP_OK) {
    Serial.println("📤 Data Sent:");
    Serial.printf("   ID          : %d\n",   dataToSend.id);
    Serial.printf("   Temperature : %.1f°C\n", dataToSend.temperature);
    Serial.printf("   Humidity    : %.1f%%\n",  dataToSend.humidity);
    Serial.printf("   Message     : %s\n",    dataToSend.message);
  } else {
    Serial.println("❌ Error sending data");
  }

  delay(3000);  // Send every 3 seconds
}
```

---

## Slave (Receiver) Code

```cpp
#include <Arduino.h>
#include <esp_now.h>
#include <WiFi.h>

// =============================================
// Data structure (must match Master)
// =============================================

typedef struct MessageData {
  int id;
  float temperature;
  float humidity;
  char message[32];
} MessageData;

MessageData receivedData;

// =============================================
// Callback Functions
// =============================================

// Called when data is received
void OnDataReceived(const esp_now_recv_info_t *recvInfo, const uint8_t *incomingData, int len) {
  memcpy(&receivedData, incomingData, sizeof(receivedData));

  Serial.println("\n📥 Data Received:");
  Serial.printf("   From MAC    : %02X:%02X:%02X:%02X:%02X:%02X\n",
    recvInfo->src_addr[0], recvInfo->src_addr[1], recvInfo->src_addr[2],
    recvInfo->src_addr[3], recvInfo->src_addr[4], recvInfo->src_addr[5]);
  Serial.printf("   ID          : %d\n",     receivedData.id);
  Serial.printf("   Temperature : %.1f°C\n", receivedData.temperature);
  Serial.printf("   Humidity    : %.1f%%\n",  receivedData.humidity);
  Serial.printf("   Message     : %s\n",     receivedData.message);
  Serial.printf("   Data Size   : %d bytes\n", len);
}

// =============================================
// Setup
// =============================================

void setup() {
  Serial.begin(115200);
  Serial.println("\n=== ESP-NOW Slave ===");

  // Set device as a Wi-Fi Station
  WiFi.mode(WIFI_STA);
  WiFi.disconnect();

  // Print MAC Address
  Serial.print("Slave MAC Address: ");
  Serial.println(WiFi.macAddress());

  // Initialize ESP-NOW
  if (esp_now_init() != ESP_OK) {
    Serial.println("❌ Error initializing ESP-NOW");
    return;
  }

  // Register receive callback
  esp_now_register_recv_cb(OnDataReceived);

  Serial.println("✅ ESP-NOW Initialized");
  Serial.println("⏳ Waiting for data...");
}

// =============================================
// Loop
// =============================================

void loop() {
  // Nothing needed here
  // Data received via callback
  delay(1000);
}
```

