## Solution: Shared Service with BehaviorSubject

### 1. Create the Shared Service

```typescript
// shared.service.ts
import { Injectable } from '@angular/core';
import { BehaviorSubject } from 'rxjs';

@Injectable({
  providedIn: 'root'
})
export class SharedService {

  private selectedBundleSource = new BehaviorSubject<any>(null);
  selectedBundle$ = this.selectedBundleSource.asObservable();

  selectBundle(bundle: any): void {
    this.selectedBundleSource.next(bundle);
  }

  clearSelectedBundle(): void {
    this.selectedBundleSource.next(null);
  }
}
```

---

### 2. Details Component (Sender)

```typescript
// details.component.ts
import { Component } from '@angular/core';
import { SharedService } from '../services/shared.service';

@Component({
  selector: 'app-details',
  templateUrl: './details.component.html'
})
export class DetailsComponent {

  bundles = [
    { id: 1, name: 'Bundle A', price: 10, description: 'Basic Bundle' },
    { id: 2, name: 'Bundle B', price: 20, description: 'Standard Bundle' },
    { id: 3, name: 'Bundle C', price: 30, description: 'Premium Bundle' },
  ];

  selectedBundleId: number | null = null;

  constructor(private sharedService: SharedService) {}

  onSelectBundle(bundle: any): void {
    this.selectedBundleId = bundle.id;        // highlight selected
    this.sharedService.selectBundle(bundle);  // send to service
  }
}
```

```html
<!-- details.component.html -->
<div class="bundles-container">

  <div
    *ngFor="let bundle of bundles"
    class="bundle-card"
    [class.selected]="selectedBundleId === bundle.id">

    <h3>{{ bundle.name }}</h3>
    <p>{{ bundle.description }}</p>
    <p>Price: {{ bundle.price }}$</p>

    <button
      (click)="onSelectBundle(bundle)"
      [class.active]="selectedBundleId === bundle.id">
      {{ selectedBundleId === bundle.id ? 'Selected ✓' : 'Select' }}
    </button>

  </div>

</div>
```

---

### 3. Another Component (Receiver)

```typescript
// another.component.ts
import { Component, OnInit, OnDestroy } from '@angular/core';
import { SharedService } from '../services/shared.service';
import { Subscription } from 'rxjs';

@Component({
  selector: 'app-another',
  templateUrl: './another.component.html'
})
export class AnotherComponent implements OnInit, OnDestroy {

  selectedBundle: any = null;
  private subscription: Subscription;

  constructor(private sharedService: SharedService) {}

  ngOnInit(): void {
    this.subscription = this.sharedService.selectedBundle$.subscribe(bundle => {
      this.selectedBundle = bundle;
      console.log('Received bundle:', bundle);
    });
  }

  ngOnDestroy(): void {
    this.subscription.unsubscribe(); // prevent memory leaks
  }
}
```

```html
<!-- another.component.html -->
<div *ngIf="selectedBundle; else noSelection">
  <h2>Selected Bundle:</h2>
  <p>Name: {{ selectedBundle.name }}</p>
  <p>Price: {{ selectedBundle.price }}$</p>
  <p>Description: {{ selectedBundle.description }}</p>
</div>

<ng-template #noSelection>
  <p>No bundle selected yet.</p>
</ng-template>
```

---

## How It Works

```
Details Component          Shared Service              Another Component
─────────────────         ────────────────            ─────────────────
User clicks Select   →    BehaviorSubject.next()  →   Subscribe gets update
                          stores latest value          & displays bundle
```

| Feature | Description |
|---------|-------------|
| `BehaviorSubject` | Holds the **last value**, new subscribers get it immediately |
| `asObservable()` | Exposes only **read** access to other components |
| `selectBundle()` | Only the service can **write** the value |
| `unsubscribe()` | Prevents **memory leaks** on destroy |

# LFO Frequency Calculator en C++

## Formule de base
La fréquence d'un LFO synchronisé au tempo est :
$$f_{LFO} = \frac{BPM}{60} \times \frac{1}{division}$$

---

```cpp
#include <iostream>
#include <string>
#include <map>
#include <iomanip>
#include <stdexcept>

// ============================================================
// Structure pour représenter une division de note
// ============================================================
struct NoteDivision {
    std::string name;       // Nom de la division (ex: "1/4")
    double      multiplier; // Multiplicateur par rapport à une mesure entière
};

// ============================================================
// Tableau des divisions de notes disponibles
// ============================================================
// multiplier = nombre de beats (noires) pour cette division
// Ex: ronde (1/1) = 4 beats, noire (1/4) = 1 beat, etc.
const std::map<int, NoteDivision> NOTE_DIVISIONS = {
    { 1,  { "1/1   - Ronde",               4.0     } },
    { 2,  { "1/2   - Blanche",             2.0     } },
    { 3,  { "1/2d  - Blanche pointée",     3.0     } },
    { 4,  { "1/4   - Noire",               1.0     } },
    { 5,  { "1/4d  - Noire pointée",       1.5     } },
    { 6,  { "1/4t  - Noire triolet",       2.0/3.0 } },
    { 7,  { "1/8   - Croche",              0.5     } },
    { 8,  { "1/8d  - Croche pointée",      0.75    } },
    { 9,  { "1/8t  - Croche triolet",      1.0/3.0 } },
    { 10, { "1/16  - Double croche",       0.25    } },
    { 11, { "1/16d - Double croche pointée",0.375  } },
    { 12, { "1/16t - Double croche triolet",1.0/6.0} },
    { 13, { "1/32  - Triple croche",       0.125   } },
    { 14, { "2/1   - Carrée (2 mesures)",  8.0     } },
    { 15, { "4/1   - (4 mesures)",         16.0    } },
};

// ============================================================
// Calcul de la fréquence du LFO
//
// Paramètres :
//   bpm        - Tempo en battements par minute
//   multiplier - Durée de la division en nombre de beats
//
// Retourne : fréquence en Hz
// ============================================================
double calculateLFOFrequency(double bpm, double multiplier) {
    if (bpm <= 0.0) {
        throw std::invalid_argument("Le BPM doit etre positif.");
    }
    if (multiplier <= 0.0) {
        throw std::invalid_argument("Le multiplicateur doit etre positif.");
    }

    // Durée d'un beat en secondes
    double beatDuration = 60.0 / bpm;

    // Durée de la division en secondes
    double divisionDuration = beatDuration * multiplier;

    // Fréquence = 1 / période
    return 1.0 / divisionDuration;
}

// ============================================================
// Calcul de la période du LFO
// ============================================================
double calculateLFOPeriod(double bpm, double multiplier) {
    return 1.0 / calculateLFOFrequency(bpm, multiplier);
}

// ============================================================
// Affichage du menu des divisions
// ============================================================
void displayDivisions() {
    std::cout << "\n=== Divisions de notes disponibles ===\n";
    for (const auto& [key, div] : NOTE_DIVISIONS) {
        std::cout << "  [" << std::setw(2) << key << "] " << div.name << "\n";
    }
    std::cout << "======================================\n";
}

// ============================================================
// Affichage des résultats
// ============================================================
void displayResults(double bpm, const NoteDivision& div) {
    double freq   = calculateLFOFrequency(bpm, div.multiplier);
    double period = calculateLFOPeriod(bpm, div.multiplier);

    std::cout << std::fixed << std::setprecision(4);
    std::cout << "\n╔══════════════════════════════════════╗\n";
    std::cout << "║         RÉSULTAT LFO                 ║\n";
    std::cout << "╠══════════════════════════════════════╣\n";
    std::cout << "║ Tempo        : " << std::setw(8) << bpm
              << " BPM            ║\n";
    std::cout << "║ Division     : " << div.name << "\n";
    std::cout << "║ Fréquence    : " << std::setw(10) << freq
              << " Hz          ║\n";
    std::cout << "║ Période      : " << std::setw(10) << period
              << " s           ║\n";
    std::cout << "╚══════════════════════════════════════╝\n";
}

// ============================================================
// Mode interactif
// ============================================================
void interactiveMode() {
    double bpm    = 0.0;
    int    choice = 0;

    std::cout << "\n╔══════════════════════════════════════╗\n";
    std::cout << "║    LFO FREQUENCY CALCULATOR          ║\n";
    std::cout << "║    Synchronisation Tempo -> LFO      ║\n";
    std::cout << "╚══════════════════════════════════════╝\n";

    // Saisie du BPM
    while (true) {
        std::cout << "\nEntrez le tempo (BPM) [20-999] : ";
        if (std::cin >> bpm && bpm >= 20.0 && bpm <= 999.0) {
            break;
        }
        std::cin.clear();
        std::cin.ignore(1000, '\n');
        std::cout << "  ⚠ Valeur invalide. Réessayez.\n";
    }

    // Saisie de la division
    displayDivisions();
    while (true) {
        std::cout << "Choisissez une division [1-" 
                  << NOTE_DIVISIONS.size() << "] : ";
        if (std::cin >> choice && NOTE_DIVISIONS.count(choice)) {
            break;
        }
        std::cin.clear();
        std::cin.ignore(1000, '\n');
        std::cout << "  ⚠ Choix invalide. Réessayez.\n";
    }

    // Affichage du résultat
    displayResults(bpm, NOTE_DIVISIONS.at(choice));

    // Afficher toutes les divisions pour ce BPM ?
    char all;
    std::cout << "\nAfficher toutes les divisions pour "
              << bpm << " BPM ? (o/n) : ";
    std::cin >> all;

    if (all == 'o' || all == 'O') {
        std::cout << "\n";
        std::cout << std::left
                  << std::setw(30) << "Division"
                  << std::setw(15) << "Fréquence (Hz)"
                  << std::setw(15) << "Période (s)"
                  << "\n";
        std::cout << std::string(60, '-') << "\n";

        for (const auto& [key, div] : NOTE_DIVISIONS) {
            double f = calculateLFOFrequency(bpm, div.multiplier);
            double p = calculateLFOPeriod(bpm, div.multiplier);
            std::cout << std::fixed << std::setprecision(6)
                      << std::setw(30) << div.name
                      << std::setw(15) << f
                      << std::setw(15) << p
                      << "\n";
        }
    }
}

// ============================================================
// Main
// ============================================================
int main(int argc, char* argv[]) {

    // Mode ligne de commande : ./lfo <BPM> <division_index>
    if (argc == 3) {
        try {
            double bpm    = std::stod(argv[1]);
            int    choice = std::stoi(argv[2]);

            if (!NOTE_DIVISIONS.count(choice)) {
                throw std::invalid_argument("Division invalide.");
            }

            displayResults(bpm, NOTE_DIVISIONS.at(choice));

        } catch (const std::exception& e) {
            std::cerr << "Erreur : " << e.what() << "\n";
            std::cerr << "Usage   : " << argv[0] 
                      << " <BPM> <division_index>\n";
            return 1;
        }
    } else {
        // Mode interactif
        bool continuer = true;
        while (continuer) {
            interactiveMode();
            char rep;
            std::cout << "\nNouveau calcul ? (o/n) : ";
            std::cin >> rep;
            continuer = (rep == 'o' || rep == 'O');
        }
        std::cout << "\nAu revoir !\n";
    }

    return 0;
}
```

