    % ==========================================
    % PRIVATE PROPERTIES
    % ==========================================
    properties (Access = private)
        c = 3e8;        % Speed of light (m/s)
        k = 1.38e-23;   % Boltzmann constant (J/K)
    end

    % ==========================================
    % METHODS
    % ==========================================
    methods (Access = private)

        % ==========================================
        % MAIN CALCULATION FUNCTION
        % ==========================================
        function calculateBistatic(app)

            try
                %% --- Read Inputs ---
                % Transmitter
                Pt   = app.TxPowerField.Value;      % [W]
                Gt   = app.TxGainField.Value;        % [dBi]
                freq = app.TxFreqField.Value * 1e6;  % [MHz] -> [Hz]
                Tx   = [app.TxXField.Value, app.TxYField.Value, app.TxZField.Value];

                % Receiver
                Gr   = app.RxGainField.Value;        % [dBi]
                NF   = app.RxNFField.Value;          % [dB]
                BW   = app.RxBWField.Value * 1e3;    % [kHz] -> [Hz]
                SNRmin_dB = app.RxSNRField.Value;    % [dB]
                Rx   = [app.RxXField.Value, app.RxYField.Value, app.RxZField.Value];

                % Target
                RCS  = app.TgtRCSField.Value;        % [m²]
                Tgt  = [app.TgtXField.Value, app.TgtYField.Value, app.TgtZField.Value];

                % Environment
                L_dB = app.LossField.Value;          % [dB]
                T    = app.TempField.Value;           % [K]

                %% --- Unit Conversions ---
                Gt_lin    = 10^(Gt/10);
                Gr_lin    = 10^(Gr/10);
                NF_lin    = 10^(NF/10);
                L_lin     = 10^(L_dB/10);
                SNRmin_lin= 10^(SNRmin_dB/10);
                lambda    = app.c / freq;

                %% --- Geometric Calculations ---
                R_T = norm(Tgt - Tx);    % Tx -> Target distance
                R_R = norm(Tgt - Rx);    % Rx -> Target distance
                R_B = norm(Rx - Tx);     % Baseline (Tx -> Rx)

                % Bistatic angle
                vec_T = (Tgt - Tx) / R_T;
                vec_R = (Tgt - Rx) / R_R;
                cos_beta = dot(vec_T, -vec_R);
                cos_beta = max(-1, min(1, cos_beta));
                beta = acosd(cos_beta);   % degrees

                %% --- Bistatic Radar Equation ---
                % Pr = (Pt * Gt * Gr * lambda^2 * RCS) /
                %      ((4*pi)^3 * R_T^2 * R_R^2 * L)

                numerator   = Pt * Gt_lin * Gr_lin * lambda^2 * RCS;
                denominator = (4*pi)^3 * R_T^2 * R_R^2 * L_lin;

                Pr = numerator / denominator;
                Pr_dBW = 10*log10(Pr);

                %% --- Noise Power ---
                Pn = app.k * T * BW * NF_lin;
                Pn_dBW = 10*log10(Pn);

                %% --- SNR ---
                SNR     = Pr / Pn;
                SNR_dB  = 10*log10(SNR);

                % Detection Margin
                margin_dB = SNR_dB - SNRmin_dB;

                %% --- Maximum Range Product (Oval of Cassini) ---
                % R_T * R_R <= R_max_product
                % Maximum range for equal distances:
                % R_T = R_R = R_max_sym
                % Pr_min = Pn * SNRmin
                Pr_min = Pn * SNRmin_lin;

                R_max_product = sqrt(sqrt(...
                    (Pt * Gt_lin * Gr_lin * lambda^2 * RCS) / ...
                    ((4*pi)^3 * Pr_min * L_lin)));

                % Oval of Cassini semi-axis
                oval_k2 = sqrt((Pt * Gt_lin * Gr_lin * lambda^2 * RCS) / ...
                               ((4*pi)^3 * Pr_min * L_lin));

                %% --- Detection Decision ---
                detected = (SNR_dB >= SNRmin_dB);

                %% --- Update Results Tab ---
                app.updateResults(Pt, Gt, Gr, freq, lambda, ...
                    R_T, R_R, R_B, beta, ...
                    Pr, Pr_dBW, Pn, Pn_dBW, ...
                    SNR_dB, SNRmin_dB, margin_dB, ...
                    R_max_product, oval_k2, detected);

                %% --- Update Geometry Plots ---
                app.plotGeometry(Tx, Rx, Tgt, R_T, R_R, R_B, ...
                                  oval_k2, detected);

                %% --- Log ---
                app.addLog(sprintf(['[%s] Cálculo OK | ' ...
                    'Alvo: (%.0f,%.0f,%.0f) m | ' ...
                    'SNR=%.2f dB | Deteção=%s'], ...
                    datestr(now,'HH:MM:SS'), ...
                    Tgt(1), Tgt(2), Tgt(3), ...
                    SNR_dB, ...
                    string(detected)));

                % Switch to results tab
                app.TabGroup.SelectedTab = app.ResultsTab;

            catch ME
                app.addLog(sprintf('[ERRO] %s', ME.message));
                uialert(app.UIFigure, ME.message, 'Erro no Cálculo', ...
                    'Icon','error');
            end
        end

        % ==========================================
        % UPDATE RESULTS UI
        % ==========================================
        function updateResults(app, Pt, Gt, Gr, freq, lambda, ...
                R_T, R_R, R_B, beta, ...
                Pr, Pr_dBW, Pn, Pn_dBW, ...
                SNR_dB, SNRmin_dB, margin_dB, ...
                R_max_product, oval_k2, detected)

            % Status
            if detected
                app.StatusIndicator.Text        = '✔  ALVO DETETADO';
                app.StatusIndicator.FontColor   = [0.18 0.72 0.20];
                app.StatusIndicator.BackgroundColor = [0.90 1.00 0.90];
            else
                app.StatusIndicator.Text        = '✘  ALVO NÃO DETETADO';
                app.StatusIndicator.FontColor   = [0.85 0.10 0.10];
                app.StatusIndicator.BackgroundColor = [1.00 0.90 0.90];
            end

            % Distances
            app.RTxValue.Text   = sprintf('%.2f km  (%.0f m)', R_T/1e3, R_T);
            app.RRxValue.Text   = sprintf('%.2f km  (%.0f m)', R_R/1e3, R_R);
            app.RBaseValue.Text = sprintf('%.2f km  (%.0f m)', R_B/1e3, R_B);
            app.BetaValue.Text  = sprintf('%.2f °', beta);
            app.LambdaValue.Text= sprintf('%.4f m  (f = %.2f MHz)', ...
                                          lambda, freq/1e6);

            % Power
            app.PrValue.Text      = sprintf('%.2e W  (%.2f dBW)', Pr, Pr_dBW);
            app.NoiseValue.Text   = sprintf('%.2e W  (%.2f dBW)', Pn, Pn_dBW);
            app.SNRCalcValue.Text = sprintf('%.2f dB', SNR_dB);
            app.SNRMinValue.Text  = sprintf('%.2f dB', SNRmin_dB);

            % Margin color
            if margin_dB >= 0
                app.MarginValue.FontColor = [0.18 0.72 0.20];
            else
                app.MarginValue.FontColor = [0.85 0.10 0.10];
            end
            app.MarginValue.Text = sprintf('%.2f dB', margin_dB);

            % Max range
            app.MaxRangeValue.Text  = sprintf('%.2f km  (simétrico)', ...
                                               R_max_product/1e3);
            app.OvalInfoValue.Text  = sprintf('k² = %.4e m²', oval_k2);
        end

        % ==========================================
        % PLOT GEOMETRY (2D + 3D)
        % ==========================================
        function plotGeometry(app, Tx, Rx, Tgt, R_T, R_R, R_B, oval_k2, detected)

            %% ---------- 2D Plot ----------
            ax = app.GeometryAxes;
            cla(ax);
            hold(ax, 'on');
            grid(ax, 'on');
            ax.GridAlpha = 0.3;

            % Draw Oval of Cassini
            try
                theta = linspace(0, 2*pi, 800);
                % Place Tx and Rx on x-axis symmetrically
                d = R_B / 2;
                % r(theta): solve r^4 - 2d^2*cos(2θ)*r^2 - (k^4-d^4) = 0
                A = 1;
                B = -2 * d^2 * cos(2*theta);
                C = -(oval_k2 - d^4);
                discriminant = B.^2 - 4*A.*C;
                discriminant(discriminant < 0) = 0;
                r2 = (-B + sqrt(discriminant)) / 2;
                r2(r2 < 0) = 0;
                r = sqrt(r2);

                % Center of baseline
                cx = (Tx(1) + Rx(1)) / 2;
                cy = (Tx(2) + Rx(2)) / 2;
                angle_base = atan2(Rx(2)-Tx(2), Rx(1)-Tx(1));

                x_oval = cx + r .* cos(theta + angle_base);
                y_oval = cy + r .* sin(theta + angle_base);

                fill(ax, x_oval, y_oval, [0.7 0.85 1.0], ...
                    'EdgeColor', [0.2 0.4 0.8], 'LineWidth', 1.5, ...
                    'FaceAlpha', 0.25, 'DisplayName', 'Zona de Deteção');
            catch
                % Skip oval if computation fails
            end

            % Draw lines Tx->Target and Rx->Target
            plot(ax, [Tx(1) Tgt(1)], [Tx(2) Tgt(2)], ...
                '--', 'Color', [0.9 0.5 0.1], 'LineWidth', 1.5, ...
                'DisplayName', sprintf('R_T = %.1f km', R_T/1e3));
            plot(ax, [Rx(1) Tgt(1)], [Rx(2) Tgt(2)], ...
                '--', 'Color', [0.1 0.5 0.9], 'LineWidth', 1.5, ...
                'DisplayName', sprintf('R_R = %.1f km', R_R/1e3));

            % Baseline
            plot(ax, [Tx(1) Rx(1)], [Tx(2) Rx(2)], ...
                '-', 'Color', [0.5 0.5 0.5], 'LineWidth', 2, ...
                'DisplayName', sprintf('Baseline = %.1f km', R_B/1e3));

            % Antenna icons
            scatter(ax, Tx(1), Tx(2), 180, [0.9 0.4 0.1], '^', ...
                'filled', 'DisplayName', 'Transmissor (Tx)', 'LineWidth', 2);
            scatter(ax, Rx(1), Rx(2), 180, [0.1 0.4 0.9], 's', ...
                'filled', 'DisplayName', 'Recetor (Rx)', 'LineWidth', 2);

            % Target
            if detected
                scatter(ax, Tgt(1), Tgt(2), 200, [0.18 0.72 0.20], 'p', ...
                    'filled', 'DisplayName', 'Alvo (DETETADO)', 'LineWidth', 2);
            else
                scatter(ax, Tgt(1), Tgt(2), 200, [0.85 0.10 0.10], 'p', ...
                    'filled', 'DisplayName', 'Alvo (NÃO DETETADO)', 'LineWidth', 2);
            end

            % Labels
            text(ax, Tx(1), Tx(2), '  Tx', 'FontSize', 11, ...
                'FontWeight','bold', 'Color', [0.9 0.4 0.1]);
            text(ax, Rx(1), Rx(2), '  Rx', 'FontSize', 11, ...
                'FontWeight','bold', 'Color', [0.1 0.4 0.9]);
            text(ax, Tgt(1), Tgt(2), '  Alvo', 'FontSize', 11, ...
                'FontWeight','bold', 'Color', [0 0 0]);

            legend(ax, 'Location', 'bestoutside', 'FontSize', 9);
            xlabel(ax, 'X (m)', 'FontSize', 10);
            ylabel(ax, 'Y (m)', 'FontSize', 10);
            title(ax, 'Geometria do Sistema Bistático (Vista 2D)', ...
                'FontSize', 12, 'FontWeight','bold');
            axis(ax, 'equal');
            hold(ax, 'off');

            %% ---------- 3D Plot ----------
            ax3 = app.Geometry3DAxes;
            cla(ax3);
            hold(ax3, 'on');
            grid(ax3, 'on');
            ax3.GridAlpha = 0.3;

            % Draw lines
            plot3(ax3, [Tx(1) Tgt(1)], [Tx(2) Tgt(2)], [Tx(3) Tgt(3)], ...
                '--', 'Color', [0.9 0.5 0.1], 'LineWidth', 2);
            plot3(ax3, [Rx(1) Tgt(1)], [Rx(2) Tgt(2)], [Rx(3) Tgt(3)], ...
                '--', 'Color', [0.1 0.5 0.9], 'LineWidth', 2);
            plot3(ax3, [Tx(1) Rx(1)], [Tx(2) Rx(2)], [Tx(3) Rx(3)], ...
                '-', 'Color', [0.5 0.5 0.5], 'LineWidth', 2);

            % Vertical projections to ground (z=0)
            for pt = {Tx, Rx, Tgt}
                p = pt{1};
                plot3(ax3, [p(1) p(1)], [p(2) p(2)], [0 p(3)], ...
                    ':', 'Color', [0.7 0.7 0.7], 'LineWidth', 1);
            end

            % Scatter
            scatter3(ax3, Tx(1), Tx(2), Tx(3), 180, ...
                [0.9 0.4 0.1], '^', 'filled');
            scatter3(ax3, Rx(1), Rx(2), Rx(3), 180, ...
                [0.1 0.4 0.9], 's', 'filled');

            if detected
                scatter3(ax3, Tgt(1), Tgt(2), Tgt(3), 200, ...
                    [0.18 0.72 0.20], 'p', 'filled');
            else
                scatter3(ax3, Tgt(1), Tgt(2), Tgt(3), 200, ...
                    [0.85 0.10 0.10], 'p', 'filled');
            end

            % Labels
            text(ax3, Tx(1), Tx(2), Tx(3), '  Tx', 'FontSize', 10, ...
                'FontWeight','bold', 'Color', [0.9 0.4 0.1]);
            text(ax3, Rx(1), Rx(2), Rx(3), '  Rx', 'FontSize', 10, ...
                'FontWeight','bold', 'Color', [0.1 0.4 0.9]);
            text(ax3, Tgt(1), Tgt(2), Tgt(3), '  Alvo', 'FontSize', 10, ...
                'FontWeight','bold', 'Color', [0 0 0]);

            xlabel(ax3, 'X (m)', 'FontSize', 9);
            ylabel(ax3, 'Y (m)', 'FontSize', 9);
            zlabel(ax3, 'Z (m)', 'FontSize', 9);
            title(ax3, 'Geometria do Sistema Bistático (Vista 3D)', ...
                'FontSize', 12, 'FontWeight','bold');
            view(ax3, 45, 30);
            hold(ax3, 'off');
        end

        % ==========================================
        % LOG FUNCTION
        % ==========================================
        function addLog(app, msg)
            current = app.LogTextArea.Value;
            if ischar(current)
                current = {current};
            end
            app.LogTextArea.Value = [current; {msg}];
        end

        % ==========================================
        % CLEAR / RESET
        % ==========================================
        function resetFields(app)
            % Transmitter defaults
            app.TxPowerField.Value  = 1000;
            app.TxGainField.Value   = 30;
            app.TxFreqField.Value   = 3000;
            app.TxXField.Value      = 0;
            app.TxYField.Value      = 0;
            app.TxZField.Value      = 10;

            % Receiver defaults
            app.RxGainField.Value   = 25;
            app.RxNFField.Value     = 5;
            app.RxBWField.Value     = 100;
            app.RxSNRField.Value    = 13;
            app.RxXField.Value      = 50000;
            app.RxYField.Value      = 0;
            app.RxZField.Value      = 5;

            % Target defaults
            app.TgtRCSField.Value   = 1;
            app.TgtXField.Value     = 25000;
            app.TgtYField.Value     = 15000;
            app.TgtZField.Value     = 1000;

            % Environment defaults
            app.LossField.Value     = 3;
            app.TempField.Value     = 290;

            app.addLog('[INFO] Campos reiniciados para valores padrão.');
        end

