# crawl_site.py
import requests
from bs4 import BeautifulSoup
import os
import re
import time
import json
import urllib.parse
from pathlib import Path
import base64
import hashlib

# ============================================================
# 配置区域
# ============================================================
BASE_URL = "https://aix4admins.blogspot.com"
OUTPUT_DIR = "local_site"
HEADERS = {
    "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
                  "AppleWebKit/537.36 (KHTML, like Gecko) "
                  "Chrome/120.0.0.0 Safari/537.36",
    "Accept-Language": "zh-CN,zh;q=0.9,en;q=0.8",
}
DELAY = 2  # 每次请求间隔秒数，避免被封
MAX_PAGES = 50  # 最多抓取文章数量（避免过多）
# ============================================================


def sanitize_filename(name):
    """清理文件名中的非法字符"""
    name = re.sub(r'[\\/*?:"<>|]', "_", name)
    name = name.strip().replace(" ", "_")
    return name[:80]  # 限制长度


def get_hash(url):
    """生成URL的短哈希，用于文件命名"""
    return hashlib.md5(url.encode()).hexdigest()[:8]


def ensure_dir(path):
    """确保目录存在"""
    Path(path).mkdir(parents=True, exist_ok=True)


def fetch_page(url, retries=3):
    """获取页面内容，带重试机制"""
    for i in range(retries):
        try:
            print(f"  [GET] {url}")
            resp = requests.get(url, headers=HEADERS, timeout=20)
            resp.raise_for_status()
            resp.encoding = "utf-8"
            return resp.text
        except Exception as e:
            print(f"  [ERROR] 第{i+1}次请求失败: {e}")
            if i < retries - 1:
                time.sleep(3)
    return None


def fetch_image(url):
    """下载图片，返回bytes"""
    try:
        resp = requests.get(url, headers=HEADERS, timeout=15)
        if resp.status_code == 200:
            return resp.content
    except Exception as e:
        print(f"  [IMG ERROR] {url}: {e}")
    return None


def get_image_ext(url, content_type=""):
    """根据URL或Content-Type获取图片扩展名"""
    url_lower = url.lower().split("?")[0]
    for ext in [".jpg", ".jpeg", ".png", ".gif", ".webp", ".svg", ".ico"]:
        if url_lower.endswith(ext):
            return ext
    if "png" in content_type:
        return ".png"
    if "gif" in content_type:
        return ".gif"
    if "webp" in content_type:
        return ".webp"
    return ".jpg"


class BlogCrawler:
    def __init__(self):
        self.output_dir = OUTPUT_DIR
        self.assets_dir = os.path.join(OUTPUT_DIR, "assets")
        self.images_dir = os.path.join(OUTPUT_DIR, "assets", "images")
        self.pages_dir = os.path.join(OUTPUT_DIR, "pages")

        ensure_dir(self.output_dir)
        ensure_dir(self.assets_dir)
        ensure_dir(self.images_dir)
        ensure_dir(self.pages_dir)

        self.posts = []        # 一级：文章列表
        self.categories = {}   # 二级：分类/标签
        self.image_cache = {}  # URL -> 本地路径映射

    def run(self):
        print("=" * 60)
        print("开始抓取博客内容...")
        print("=" * 60)

        # Step 1: 抓取首页，获取文章列表
        self.crawl_homepage()

        # Step 2: 抓取每篇文章详情
        self.crawl_posts()

        # Step 3: 抓取分类/标签页面
        self.crawl_categories()

        # Step 4: 生成本地网站
        self.generate_site()

        print("\n" + "=" * 60)
        print("✅ 完成！本地网站已生成在:", os.path.abspath(self.output_dir))
        print("打开方式: 双击", os.path.join(self.output_dir, "index.html"))
        print("=" * 60)

    # --------------------------------------------------------
    # 抓取首页及翻页
    # --------------------------------------------------------
    def crawl_homepage(self):
        print("\n[1/4] 抓取文章列表...")

        page_url = BASE_URL + "/"
        page_count = 0
        visited = set()

        while page_url and len(self.posts) < MAX_PAGES:
            if page_url in visited:
                break
            visited.add(page_url)

            html = fetch_page(page_url)
            if not html:
                break

            soup = BeautifulSoup(html, "lxml")

            # 抓取本页文章
            new_posts = self._parse_post_list(soup, page_url)
            if not new_posts:
                break

            self.posts.extend(new_posts)
            page_count += 1
            print(f"  已收集 {len(self.posts)} 篇文章 (第{page_count}页)")

            # 查找"下一页"链接
            next_link = soup.find("a", class_="blog-pager-older-link")
            if next_link and next_link.get("href"):
                page_url = next_link["href"]
                time.sleep(DELAY)
            else:
                break

        # 抓取侧边栏分类
        html = fetch_page(BASE_URL + "/")
        if html:
            soup = BeautifulSoup(html, "lxml")
            self._parse_sidebar(soup)

        print(f"  共发现 {len(self.posts)} 篇文章")

    def _parse_post_list(self, soup, current_url):
        """解析文章列表"""
        posts = []

        # Blogger通用文章选择器
        articles = soup.find_all("div", class_="post-outer")
        if not articles:
            articles = soup.find_all("article")
        if not articles:
            articles = soup.find_all("div", class_=re.compile(r"post\b"))

        for article in articles:
            post = {}

            # 标题
            title_tag = (article.find("h3", class_="post-title") or
                        article.find("h2", class_="post-title") or
                        article.find(["h1","h2","h3"], class_=re.compile("title")))
            if not title_tag:
                continue

            link_tag = title_tag.find("a") or article.find("a", rel="bookmark")
            if not link_tag:
                continue

            post["title"] = title_tag.get_text(strip=True)
            post["url"] = link_tag.get("href", "")
            if not post["url"].startswith("http"):
                post["url"] = urllib.parse.urljoin(current_url, post["url"])

            # 日期
            date_tag = (article.find("time") or
                       article.find("abbr", class_="published") or
                       article.find(class_=re.compile(r"date|time")))
            post["date"] = ""
            if date_tag:
                post["date"] = (date_tag.get("datetime") or 
                               date_tag.get("title") or 
                               date_tag.get_text(strip=True))

            # 摘要
            snippet = (article.find("div", class_="post-body") or
                      article.find("div", class_=re.compile("snippet|summary|body")))
            post["snippet"] = ""
            if snippet:
                text = snippet.get_text(strip=True)
                post["snippet"] = text[:200] + ("..." if len(text) > 200 else "")

            # 标签
            post["labels"] = []
            label_links = article.find_all("a", rel="tag")
            if not label_links:
                label_area = article.find(class_=re.compile("label|tag|categor"))
                if label_area:
                    label_links = label_area.find_all("a")
            post["labels"] = [a.get_text(strip=True) for a in label_links]

            # 封面图
            img = article.find("img")
            post["thumb"] = ""
            if img:
                src = img.get("src") or img.get("data-src") or ""
                if src:
                    post["thumb"] = src

            if post["url"] and post["title"]:
                posts.append(post)

        return posts

    def _parse_sidebar(self, soup):
        """解析侧边栏的分类/标签"""
        # 查找标签/分类小组件
        widgets = soup.find_all("div", class_=re.compile(r"widget"))

        for widget in widgets:
            # 标签云
            label_list = widget.find_all("a", href=re.compile(r"/search/label/"))
            for a in label_list:
                label = a.get_text(strip=True)
                href = a.get("href", "")
                if label and href:
                    if not href.startswith("http"):
                        href = urllib.parse.urljoin(BASE_URL, href)
                    self.categories[label] = {
                        "url": href,
                        "name": label,
                        "posts": []
                    }

        print(f"  发现 {len(self.categories)} 个分类/标签")

    # --------------------------------------------------------
    # 抓取文章详情（二级页面）
    # --------------------------------------------------------
    def crawl_posts(self):
        print(f"\n[2/4] 抓取 {len(self.posts)} 篇文章详情...")

        for i, post in enumerate(self.posts):
            print(f"  [{i+1}/{len(self.posts)}] {post['title'][:50]}")

            html = fetch_page(post["url"])
            if not html:
                post["content"] = "<p>内容加载失败</p>"
                continue

            soup = BeautifulSoup(html, "lxml")
            post["content"] = self._extract_post_content(soup, post)
            post["filename"] = f"{sanitize_filename(post['title'])}_{get_hash(post['url'])}.html"

            time.sleep(DELAY)

        print(f"  文章详情抓取完成")

    def _extract_post_content(self, soup, post):
        """提取文章正文，并处理图片"""
        # 找正文区域
        content_div = (soup.find("div", class_="post-body") or
                      soup.find("div", class_="entry-content") or
                      soup.find("article") or
                      soup.find("div", id="content"))

        if not content_div:
            return "<p>未能提取内容</p>"

        # 补全信息
        if not post.get("date"):
            date_tag = soup.find("time") or soup.find(class_=re.compile("date|published"))
            if date_tag:
                post["date"] = (date_tag.get("datetime") or 
                               date_tag.get_text(strip=True))

        if not post.get("labels"):
            label_links = soup.find_all("a", rel="tag")
            post["labels"] = [a.get_text(strip=True) for a in label_links]

        # 处理图片：下载到本地
        for img in content_div.find_all("img"):
            src = img.get("src") or img.get("data-src") or ""
            if not src:
                continue

            if not src.startswith("http"):
                src = urllib.parse.urljoin(BASE_URL, src)

            local_path = self._download_image(src)
            if local_path:
                # 计算相对路径（从pages目录到assets/images）
                rel_path = "../assets/images/" + os.path.basename(local_path)
                img["src"] = rel_path
                img["loading"] = "lazy"
                # 删除可能干扰的属性
                for attr in ["data-src", "data-original", "srcset"]:
                    if img.has_attr(attr):
                        del img[attr]

        # 处理链接：内部链接转本地
        for a in content_div.find_all("a", href=True):
            href = a["href"]
            if BASE_URL in href:
                # 查找是否在已抓取文章中
                matched = next((p for p in self.posts if p.get("url") == href), None)
                if matched and matched.get("filename"):
                    a["href"] = matched["filename"]
                else:
                    a["href"] = href  # 保留原链接，以后可能更新

        return str(content_div)

    def _download_image(self, url):
        """下载图片到本地，返回本地路径"""
        if url in self.image_cache:
            return self.image_cache[url]

        try:
            resp = requests.get(url, headers=HEADERS, timeout=15)
            if resp.status_code == 200:
                ext = get_image_ext(url, resp.headers.get("content-type", ""))
                filename = get_hash(url) + ext
                filepath = os.path.join(self.images_dir, filename)

                with open(filepath, "wb") as f:
                    f.write(resp.content)

                self.image_cache[url] = filepath
                return filepath
        except Exception as e:
            print(f"    [IMG] 下载失败 {url[:60]}: {e}")

        return None

    # --------------------------------------------------------
    # 抓取分类页面
    # --------------------------------------------------------
    def crawl_categories(self):
        print(f"\n[3/4] 抓取 {len(self.categories)} 个分类页面...")

        for label, cat in self.categories.items():
            print(f"  分类: {label}")
            html = fetch_page(cat["url"])
            if not html:
                continue

            soup = BeautifulSoup(html, "lxml")
            posts = self._parse_post_list(soup, cat["url"])

            # 关联已抓取的文章
            for p in posts:
                matched = next((x for x in self.posts if x.get("url") == p["url"]), None)
                if matched:
                    cat["posts"].append(matched)
                else:
                    cat["posts"].append(p)

            time.sleep(DELAY)

    # --------------------------------------------------------
    # 生成本地网站
    # --------------------------------------------------------
    def generate_site(self):
        print("\n[4/4] 生成本地网站...")

        # 生成CSS
        self._write_css()

        # 生成首页
        self._generate_index()

        # 生成文章详情页
        self._generate_post_pages()

        # 生成分类页
        self._generate_category_pages()

        # 生成数据JSON（可选）
        self._save_data()

        print("  网站生成完成!")

