                    thumb_html = f'<div class="post-card-img-placeholder">{emoji}</div>'
            else:
                thumb_html = '<div class="post-card-img-placeholder">📄</div>'

            labels_html = "".join(
                f'<a href="cat_{sanitize_filename(l)}.html" class="label-tag">{l}</a>'
                for l in post.get("labels", [])[:3]
            )

            cards_html += f"""
<div class="post-card">
    <a href="pages/{filename}">{thumb_html}</a>
    <div class="post-card-body">
        <div class="post-card-title">
            <a href="pages/{filename}">{post['title']}</a>
        </div>
        <div class="post-card-meta">
            <span>📅 {post.get('date', '')[:10]}</span>
        </div>
        <div class="post-card-snippet">{post.get('snippet', '')}</div>
        <div class="post-card-footer">
            <div>{labels_html}</div>
            <a href="pages/{filename}" class="read-more">阅读全文 →</a>
        </div>
    </div>
</div>"""

        # 侧边栏
        sidebar_html = self._generate_sidebar(depth="root")

        content = f"""
{stats_html}
<div class="container">
<div class="main-layout">
    <div class="main-content">
        <div style="margin-bottom:20px;">
            <div class="search-box">
                <input type="text" id="search-input" placeholder="🔍 搜索文章...">
                <button onclick="doSearch()">搜索</button>
            </div>
            <div style="text-align:right; margin-top:6px;">
                <a href="#" onclick="resetSearch(); return false;" 
                   style="font-size:0.85rem; color:#888;">清除搜索</a>
            </div>
        </div>
        <div class="posts-grid">
            {cards_html}
        </div>
    </div>
    <aside class="sidebar">
        {sidebar_html}
    </aside>
</div>
</div>"""

        html = self._base_template("首页 - AIX for Admins", content, "root")
        with open(os.path.join(self.output_dir, "index.html"), "w", encoding="utf-8") as f:
            f.write(html)
        print("  ✅ 生成 index.html")

    def _generate_sidebar(self, depth="root"):
        """生成侧边栏HTML"""
        base = "../" if depth == "page" else ""

        # 最近文章
        recent = ""
        for post in self.posts[:10]:
            fn = post.get("filename", "#")
            recent += f"""
<li>
    <a href="{base}pages/{fn}">{post['title'][:45]}</a>
    <span class="recent-post-date">{post.get('date','')[:10]}</span>
</li>"""

        # 标签云
        labels_html = ""
        for label in list(self.categories.keys())[:30]:
            fn = f"{base}cat_{sanitize_filename(label)}.html"
            count = len(self.categories[label].get("posts", []))
            labels_html += f'<a href="{fn}">{label} ({count})</a>'

        return f"""
<div class="sidebar-widget">
    <div class="widget-title">🕐 最近文章</div>
    <ul class="recent-posts-list">{recent}</ul>
</div>
<div class="sidebar-widget">
    <div class="widget-title">🏷️ 标签分类</div>
    <div class="label-cloud">{labels_html}</div>
</div>
<div class="sidebar-widget">
    <div class="widget-title">ℹ️ 关于本镜像</div>
    <p style="font-size:0.88rem;color:#666;line-height:1.7;">
        本站是 <a href="https://aix4admins.blogspot.com" target="_blank">
        aix4admins.blogspot.com</a> 的本地离线镜像，
        仅供学习参考使用，版权归原作者所有。
    </p>
</div>"""

    def _generate_post_pages(self):
        """生成每篇文章的详情页"""
        for i, post in enumerate(self.posts):
            if not post.get("filename"):
                continue

            labels_html = "".join(
                f'<a href="../cat_{sanitize_filename(l)}.html" class="label-tag">{l}</a>'
                for l in post.get("labels", [])
            )

            # 上一篇/下一篇
            nav_html = '<div class="article-nav">'
            if i > 0:
                prev_post = self.posts[i-1]
                nav_html += f"""
<a href="{prev_post.get('filename','#')}" class="nav-prev">
    ← 上一篇<strong>{prev_post['title'][:40]}</strong>
</a>"""
            else:
                nav_html += '<span></span>'

            if i < len(self.posts) - 1:
                next_post = self.posts[i+1]
                nav_html += f"""
<a href="{next_post.get('filename','#')}" class="nav-next">
    下一篇 →<strong>{next_post['title'][:40]}</strong>
</a>"""
            nav_html += '</div>'

            content = f"""
<div class="container">
<div class="main-layout">
<div class="main-content">
    <div class="breadcrumb">
        <a href="../index.html">🏠 首页</a>
        <span>›</span>
        <span>{post['title'][:40]}</span>
    </div>

    <div class="article-container">
        <div class="article-header">
            <h1 class="article-title">{post['title']}</h1>
            <div class="article-meta">
                <span>📅 {post.get('date', '未知日期')[:10]}</span>
                <span>🔗 <a href="{post['url']}" target="_blank">查看原文</a></span>
            </div>
            <div class="article-labels">{labels_html}</div>
        </div>
        <div class="article-body">
            {post.get('content', '<p>内容为空</p>')}
        </div>
    </div>

    {nav_html}
</div>
<aside class="sidebar">
    {self._generate_sidebar(depth='page')}
</aside>
</div>
</div>"""

            html = self._base_template(post['title'], content, "page")
            filepath = os.path.join(self.pages_dir, post["filename"])
            with open(filepath, "w", encoding="utf-8") as f:
                f.write(html)

        print(f"  ✅ 生成 {len(self.posts)} 篇文章页面")

    def _generate_category_pages(self):
        """生成分类页面 + 总分类索引"""
        # 总分类页
        cat_grid = ""
        for label, cat in self.categories.items():
            fn = f"cat_{sanitize_filename(label)}.html"
            count = len(cat.get("posts", []))
            cat_grid += f"""
<a href="{fn}" style="
    display:block;background:white;border-radius:8px;
    padding:16px;box-shadow:0 2px 8px rgba(0,0,0,0.1);
    text-align:center;color:#333;transition:all 0.2s;
" onmouseover="this.style.transform='translateY(-3px)'"
  onmouseout="this.style.transform=''">
    <div style="font-size:2rem;margin-bottom:8px;">🏷️</div>
    <div style="font-weight:600;">{label}</div>
    <div style="font-size:0.82rem;color:#888;margin-top:4px;">{count} 篇文章</div>
</a>"""

        content = f"""
<div class="container" style="padding-top:24px;">
    <h1 style="margin-bottom:20px;">📂 所有分类</h1>
    <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:16px;">
        {cat_grid}
    </div>
</div>"""

        html = self._base_template("所有分类", content, "root")
        with open(os.path.join(self.output_dir, "categories.html"), "w", encoding="utf-8") as f:
            f.write(html)

        # 每个分类的文章列表
        for label, cat in self.categories.items():
            fn = f"cat_{sanitize_filename(label)}.html"
            posts = cat.get("posts", [])

            cards = ""
            for post in posts:
                filename = post.get("filename", "#")
                cards += f"""
<div class="post-card">
    <div class="post-card-img-placeholder">📄</div>
    <div class="post-card-body">
        <div class="post-card-title">
            <a href="pages/{filename}">{post['title']}</a>
        </div>
        <div class="post-card-meta">
            <span>📅 {post.get('date','')[:10]}</span>
        </div>
        <div class="post-card-snippet">{post.get('snippet','')}</div>
        <div class="post-card-footer">
            <span></span>
            <a href="pages/{filename}" class="read-more">阅读 →</a>
        </div>
    </div>
</div>"""

            content = f"""
<div class="container" style="padding-top:24px;">
    <div class="category-header">
        <h1>🏷️ {label}</h1>
        <p>共 {len(posts)} 篇文章</p>
    </div>
    <div class="posts-grid">{cards}</div>
</div>"""

            html = self._base_template(f"分类: {label}", content, "root")
            with open(os.path.join(self.output_dir, fn), "w", encoding="utf-8") as f:
                f.write(html)

        print(f"  ✅ 生成 {len(self.categories)} 个分类页面")

    def _save_data(self):
        """保存数据到JSON，方便调试"""
        data = {
            "total_posts": len(self.posts),
            "total_categories": len(self.categories),
            "total_images": len(self.image_cache),
            "posts": [
                {k: v for k, v in p.items() if k != "content"}
                for p in self.posts
            ],
            "categories": {
                k: {"name": v["name"], "url": v["url"], "count": len(v["posts"])}
                for k, v in self.categories.items()
            }
        }
        with open(os.path.join(self.output_dir, "data.json"), "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False, indent=2)
        print("  ✅ 保存数据 data.json")


